INSERT INTO marine_marketing.stakeholders (id, vessel_id, company_id, searched_company_id, name, role, personal_email, professional_email, linkedin_url, status, profile_pic, location, city, region, country, country_code, birth_year, current_employer, current_employer_id, current_employer_domain, current_employer_website, current_employer_linkedin_url, recommended_email, emails_json, phones_json, job_history_json, education_json, skills_json, company_json, others_data, created_by, updated_by, deleted_by, created_at, updated_at, deleted_at) VALUES (277, 152, 155, null, 'Mohd Rimzi', 'Operation Executive', null, null, 'https://www.linkedin.com/in/mohd-ashrafi-rimzi-71218854', 'not queued', null, 'United Arab Emirates', null, '', 'United Arab Emirates', 'AE', 1984, 'PACIFIC INTERNATIONAL LINES, Dubai', null, null, null, null, 'saamimarinemarketing@gmail.com', '"[]"', '"[]"', '"[{\\"start_date\\":\\"2011-01-01\\",\\"end_date\\":\\"Present\\",\\"company\\":\\"PACIFIC INTERNATIONAL LINES, Dubai\\",\\"company_name\\":\\"PACIFIC INTERNATIONAL LINES, Dubai\\",\\"company_id\\":null,\\"company_linkedin_url\\":null,\\"department\\":\\"C_suite\\",\\"title\\":\\"Operation Executive\\",\\"highest_level\\":\\"cxo\\",\\"description\\":\\"\\\\u2022Presently handling of 3 sectors: RGS, AMI & CSG (finalizing discharge list and load List and sending booking forecast to the planner. \\\\u2022Co-ordinate & follow up with the port officials & shipping agents to avoid delay in the berthing of the Vessel. \\\\u2022Follow up with the port authorities for quicker discharging of the cargo. \\\\u2022Coordinating with feeder operators for bookings and giving space accordingly. \\\\u2022Checking manifest and giving priority to reefers and foodstuff. \\\\u2022Inform port of loading if there are any roll over\\\\u2019s. \\\\u2022Familiar with plan master. \\\\u2022Coordinating with planner in regards to the vessel discharge and loading. \\\\u2022Once plan received from regional planner, sending the same to the terminal & cross checking the terminal plan with our plan. \\\\u2022Going on board on arrival of the vessel and follow up with the plan for discharging & Loading of cargo from the ship and finalizing along with the planner and Chief Officer.(If there are any changes coordinating with stowage). \\\\u2022Registering the Vessel after berthing. \\\\u2022Following up with Cargo operation and technical and other Services onboard. \\\\u2022Once vessel sailed, sending the TDR to the next port. \\\\u2022Checking & approving port bills such as Stevedoring \\\\/ Marine \\\\/ Medical \\\\/Fresh water supply & cash to Master. \\\\u2022Ship crews handling. \\\\u2022Fulfilling the requirement of the Vessel prior to port clearance, updating all the detail on a web based system (WEBCSM) to Singapore H.Q\\",\\"last_updated\\":\\"2024-10-05T00:23:44.745878\\",\\"sub_department\\":\\"Operations_executive\\",\\"is_current\\":true},{\\"start_date\\":\\"2010-01-01\\",\\"end_date\\":\\"2010-12-01\\",\\"company\\":\\"PACIFIC INTERNATIONAL LINES, Dubai\\",\\"company_name\\":\\"PACIFIC INTERNATIONAL LINES, Dubai\\",\\"company_id\\":null,\\"company_linkedin_url\\":null,\\"department\\":\\"\\",\\"title\\":\\"Imports and Export Executive\\",\\"highest_level\\":\\"individual contributor\\",\\"description\\":\\"Worked as a shipping assistant in the Import\\\\/ Export Dept. The job deals with handling customer Service\\\\/DO counter and Export counter. The job also dealt with coordinating with shippers in the local & overseas market through email, phone & preparing necessary shipping documents \\\\u2022Downloading manifest. \\\\u2022Sending Arrival notice \\\\/ Electronic Pre-Alert Shipment Advice \\\\u2022Creating partner code \\\\u2022Issuing Delivery Order & Invoices Pertaining to the Shipments \\\\u2022Monitoring and creating reports for D.G & Reefer cargoes , Damaged containers \\\\u2022Follow up with Consignee for pending overdue shipments at Jebel Ali port.\\",\\"last_updated\\":\\"2024-10-05T00:23:44.745878\\",\\"sub_department\\":\\"\\",\\"is_current\\":false},{\\"start_date\\":\\"2007-08-01\\",\\"end_date\\":\\"2009-09-01\\",\\"company\\":\\"Sama Dubai\\",\\"company_name\\":\\"Sama Dubai\\",\\"company_id\\":20052,\\"company_linkedin_url\\":\\"https:\\\\/\\\\/www.linkedin.com\\\\/company\\\\/sama-dubai\\",\\"department\\":\\"Sales\\",\\"title\\":\\"Sales and Marketing Executive\\",\\"highest_level\\":\\"individual contributor\\",\\"description\\":\\"\\\\u2022Handling of all sales inquiries local and overseas. \\\\u2022Providing investment ideas to customers for free hold properties. \\\\u2022Maintaining proper sales inquiries record and updating excel sheet for available properties. \\\\u2022Dealing with international investor as well as overseas and local customers. \\\\u2022Preparing presentations on coming project & prepare report on each projects and developers \\\\u2022Keep updating information\\\\u2019s on current and upcoming projects \\\\u2022Preparation of corporate marketing analysis report (CMA), on each property. \\\\u2022Manage Exhibitions, Marketing and its requirements. \\\\u2022Ensuring Direct and resale transactions of properties are carried out smoothly. \\\\u2022Working as a Team member of a small Self-managed team (SMT) and Ensuring initial Disbursals are processed error-free in a locked Turnaround time (TAT). \\\\u2022Coordinating with other departments to streamline the entire process of finance approval. \\\\u2022Working closely with Management to deliver customer satisfaction. \\\\u2022Interview the Customer and assess their requirements & prepare all the necessary documents in order to transfer.\\",\\"last_updated\\":\\"2024-10-05T00:23:44.745878\\",\\"sub_department\\":\\"Accounts\\",\\"is_current\\":false},{\\"start_date\\":\\"2006-02-01\\",\\"end_date\\":\\"2006-07-01\\",\\"company\\":\\"DHL EXPRESS\\",\\"company_name\\":\\"DHL EXPRESS\\",\\"company_id\\":null,\\"company_linkedin_url\\":null,\\"department\\":\\"Operations\\",\\"title\\":\\"Logistics and Customer Service and NCI Agent\\",\\"highest_level\\":\\"individual contributor\\",\\"description\\":\\"\\\\u2022Maintain an excellent relation with the Customers i.e. subject to complete paper work in the shortest possible time thereby leading to customer delight. \\\\u2022Handle customer\\\\u2019s objections & queries in a professional manner to maintain the customer\\\\u2019s faith in Services. \\\\u2022Catering to customer\\\\u2019s requirements and providing quality service to retain existing customers and gain more the help of good word of mouth. \\\\u2022Respond to any queries relating to projects both from internal and external customers in a timely and professional manner. \\\\u2022Provide a high level of customer service and professionalism taking into account the consideration that all customers have an express requirement and are looking for instant and immediate action. \\\\u2022Full coordination for all Import and export shipments. \\\\u2022Coordination between exporter and consignee. \\\\u2022Coordination with freight forwarders for speedy shipment deliveries. \\\\u2022Coordination with customs brokers for government formalities as and when required. \\\\u2022Keeping a record of company\\\\u2019s stock and coordinating with Senior Management of requirements as and when required. \\\\u2022Issuing Purchase orders and keeping a track of each shipment from the date of issue till the date goods arrived to the warehouse. \\\\u2022Issuing & certifying invoices from Chamber of Commerce. \\\\u2022Calculating freight, customs & insurance cost for all export shipments.\\",\\"last_updated\\":\\"2024-10-05T00:23:44.745878\\",\\"sub_department\\":\\"Logistics\\",\\"is_current\\":false}]"', '"[{\\"major\\":\\"International Business\\",\\"school\\":\\"AMERICAN COLLAGE OF DUBAI\\",\\"degree\\":\\"Bachelor of Business Administration (B.B.A.)\\",\\"start\\":null,\\"end\\":null}]"', '"[]"', '"[]"', '"{\\"profile_list\\":{\\"id\\":29016828,\\"name\\":\\"API Contacts\\"},\\"id\\":64991393,\\"links\\":{\\"linkedin\\":\\"https:\\\\/\\\\/www.linkedin.com\\\\/in\\\\/mohd-ashrafi-rimzi-71218854\\"},\\"region_latitude\\":23.424076,\\"region_longitude\\":53.847818,\\"npi_data\\":null,\\"tags\\":[{\\"id\\":25493700,\\"name\\":\\"API Contacts\\"}],\\"current_work_email\\":null,\\"current_personal_email\\":null}"', null, null, null, '2025-08-20 21:28:54', '2025-08-20 21:28:54', null);
