INSERT INTO marine_marketing.stakeholders (id, vessel_id, company_id, searched_company_id, name, role, personal_email, professional_email, linkedin_url, status, profile_pic, location, city, region, country, country_code, birth_year, current_employer, current_employer_id, current_employer_domain, current_employer_website, current_employer_linkedin_url, recommended_email, emails_json, phones_json, job_history_json, education_json, skills_json, company_json, others_data, created_by, updated_by, deleted_by, created_at, updated_at, deleted_at) VALUES (316, 155, 161, null, 'Michalis Pytharoulis', 'Technical Superintendent', null, null, 'https://www.linkedin.com/in/michalis-pytharoulis-5bb34b66', 'searching', 'https://d2gjqh9j26unp0.cloudfront.net/profilepic/e078148e96e5dae506ce4fc36c9ff44e', 'Greece', null, '', 'Greece', 'GR', null, 'Evalend Shipping Co. S.A.', null, null, null, null, null, '"[]"', '"[]"', '"[{\\"start_date\\":\\"2023-08-01\\",\\"end_date\\":\\"Present\\",\\"company\\":\\"Evalend Shipping Co. S.A.\\",\\"company_name\\":\\"Evalend Shipping Co. S.A.\\",\\"company_id\\":null,\\"company_linkedin_url\\":null,\\"department\\":\\"Engineering\\",\\"title\\":\\"Technical Superintendent\\",\\"highest_level\\":\\"senior\\",\\"description\\":\\"\\",\\"last_updated\\":\\"2025-08-11T01:03:26.496636\\",\\"sub_department\\":\\"Systems\\",\\"is_current\\":true},{\\"start_date\\":\\"2022-08-01\\",\\"end_date\\":\\"2023-08-01\\",\\"company\\":\\"Diligent Holdings S.A.\\",\\"company_name\\":\\"Diligent Holdings S.A.\\",\\"company_id\\":37392439,\\"company_linkedin_url\\":\\"https:\\\\/\\\\/www.linkedin.com\\\\/company\\\\/diligent-holdings\\",\\"department\\":\\"Engineering\\",\\"title\\":\\"Technical Superintendent for Bulk Carriers with deck cranes\\",\\"highest_level\\":\\"senior\\",\\"description\\":\\"\\\\u2022 Follow up & monitoring the PMS with all the appropriate info in order to schedule effectively the various maintenance activities & record date & time of inspections, tests & results; \\\\u2022 Reviews all reports concerning the quality control of purchased fuel oils, used lub oil, cooling & boiler water & proposes actions to be taken, depending on the outcomes & the recommendations provided by the approved laboratories; \\\\u2022 Evaluates quotations & makes relevant propositions to the Technical Manager for final approval; \\\\u2022 Ensuring vessel\\\\u2019s compliance with the latest Class & Flag rules & regulations; \\\\u2022 Monitoring of vessels\\\\u2019 main & auxiliary engines\\\\u2019 performance & cons, evaluates it against accepted standards & proposes actions to be taken to the Technical Manager; \\\\u2022 Verification of safety, quality, environmental & energy performance of the vessels during the onboard visits; \\\\u2022 Keeps myself updated with new developments in the area of my responsibility; \\\\u2022 Reports any non-conformities, hazardous or accidental situation that may witness or be involved in to the immediate supervisor; \\\\u2022 Comply with HSQE requirements as required by CMS; \\\\u2022 Provides guidance & assistance to vessels\' engineers being in contact with them at regular intervals; \\\\u2022 Follows up the survey status of each vessel being aware of the contact of such surveys arranged by the Technical Coordinator; \\\\u2022 Follows up condition evaluation reports from third parties & arranges for the settlement of any outstanding issues in collaboration with HSQE Dep\'t; \\\\u2022 Collaborates with the Operations Dep\'t for selecting the optimum & safer time & place for performing preventive maintenance works; \\\\u2022 Reviews vessels\' requisitions for spare parts, engine stores & reconditioning of spares & forwards these to the Purchasing Dep\'t for further action; \\\\u2022 Identifies min qt\'y of spare parts to be retained on board; \\\\u2022 ERP DANAOS & BENEFIT\\",\\"last_updated\\":\\"2025-08-11T01:03:26.496636\\",\\"sub_department\\":\\"\\",\\"is_current\\":false},{\\"start_date\\":\\"2021-01-01\\",\\"end_date\\":\\"2022-02-01\\",\\"company\\":\\"Asterismos Navigation Corporation\\",\\"company_name\\":\\"Asterismos Navigation Corporation\\",\\"company_id\\":null,\\"company_linkedin_url\\":null,\\"department\\":\\"\\",\\"title\\":\\"Deputy Fleet Manager of Technical Department for Bulk Carriers with deck cranes\\",\\"highest_level\\":\\"individual contributor\\",\\"description\\":\\"\\\\u2022 Monitoring of vessels\\\\u2019 performance & maintenance through screening technical records & reports; \\\\u2022 Attendances to assess & evaluate vessels\\\\u2019 technical condition and assuring vessels\\\\u2019 compliance with PMS; \\\\u2022 Follow up problems, technical defects reported to the office, until corrective action is verified; \\\\u2022 Ensuring vessel\\\\u2019s compliance with the latest Class and Flag rules & regulations; \\\\u2022 Monitoring of vessels\\\\u2019 preparation for audits (RightShip, PSC, Flag &Classification Surveys, ISM & ISPS) & attendances; \\\\u2022 Instructions to Chief Engineers on the actions to be taken in order to correct performance & technical deficiencies; \\\\u2022 Ensuring that all vessels operate safely, efficiently and cost effectively; \\\\u2022 Budgeting, cost control and monitoring of running expenses; \\\\u2022 Crew appraisals; \\\\u2022 Purchasing management for bunkers, lubricants, chemicals & paints; \\\\u2022 Monitoring requisitions for spare parts & stores following by analysis of performance \\\\/ inventory reports at the most competitive costs; \\\\u2022 Pre-purchase surveys and supervision of Sale and Purchase processes; \\\\u2022 Attendances to dry-dockings, responsible for the specification preparation & for commercial negotiation; \\\\u2022 Calculation and preparation of environmental reports (EEOI, MRV & SEEMP Part II)\\",\\"last_updated\\":\\"2025-08-11T01:03:26.496636\\",\\"sub_department\\":\\"\\",\\"is_current\\":false},{\\"start_date\\":\\"2018-09-01\\",\\"end_date\\":\\"2021-01-01\\",\\