INSERT INTO marine_marketing.stakeholders (id, vessel_id, company_id, searched_company_id, name, role, personal_email, professional_email, linkedin_url, status, profile_pic, location, city, region, country, country_code, birth_year, current_employer, current_employer_id, current_employer_domain, current_employer_website, current_employer_linkedin_url, recommended_email, emails_json, phones_json, job_history_json, education_json, skills_json, company_json, others_data, created_by, updated_by, deleted_by, created_at, updated_at, deleted_at) VALUES (403, null, 174, null, 'Soumya Ojha', 'Technical Superintendent', null, 'soumya.o@norseshipmanagement.com', 'https://www.linkedin.com/in/soumya-ojha-marine-engineer', 'progress', null, 'Singapore', null, '', 'Singapore', 'SG', null, 'NORSE SHIP MANAGEMENT', 50678854, 'norseshipmanagement.com', 'https://norseshipmanagement.com', 'https://www.linkedin.com/company/norse-ship-management-pte-ltd', 'soumya.o@norseshipmanagement.com', '[{"type": "professional", "email": "soumya.o@norseshipmanagement.com", "grade": "A", "smtp_valid": "valid", "last_validation_check": "2025-08-08"}]', '[]', '[{"title": "Technical Superintendent", "company": "NORSE SHIP MANAGEMENT", "end_date": "Present", "company_id": 50678854, "department": "Engineering", "is_current": true, "start_date": "2025-04-01", "description": "", "company_name": "NORSE SHIP MANAGEMENT", "last_updated": "2025-07-07T09:04:28.968763", "highest_level": "senior", "sub_department": "Systems", "company_linkedin_url": "https://www.linkedin.com/company/norse-ship-management-pte-ltd"}, {"title": "Marine Chief Engineer", "company": "NORSE SHIP MANAGEMENT", "end_date": "2025-03-01", "company_id": 50678854, "department": "Engineering", "is_current": false, "start_date": "2024-12-01", "description": "", "company_name": "NORSE SHIP MANAGEMENT", "last_updated": "2025-07-07T09:04:28.968763", "highest_level": "senior", "sub_department": "Mechanical", "company_linkedin_url": "https://www.linkedin.com/company/norse-ship-management-pte-ltd"}, {"title": "Technical Manager", "company": "KAIZEN OFFSHORE & MARINE SOLUTIONS PTE LTD", "end_date": "2024-12-01", "company_id": 25976049, "department": "Engineering", "is_current": false, "start_date": "2023-01-01", "description": "I oversaw the execution of ship repair works at anchorage and shipyards, ensuring precision and quality. My role involved in preparing proposals, estimations, and managing sub-contracts, procurement, and overall repair costs. I excelled in fostering strong relationships with clients and shipowners, providing competitive repair cost estimates, and managing bids for modifications and projects. With expertise in tender documentation, project scheduling, and contractor evaluation, I ensured efficient negotiation, invoicing, and seamless billing for all onboard activities.", "company_name": "KAIZEN OFFSHORE & MARINE SOLUTIONS PTE LTD", "last_updated": "2025-07-07T09:04:28.968763", "highest_level": "manager", "sub_department": "", "company_linkedin_url": "https://www.linkedin.com/company/kaizen-offshore-marine-solutions-pte-ltd"}, {"title": "Technical Manager", "company": "SEAGULL PTE. LTD.", "end_date": "2023-01-01", "company_id": 4840547, "department": "Engineering", "is_current": false, "start_date": "2022-02-01", "description": "I demonstrated expertise in preparing proposals, estimations, and managing sub-contracts, procurement, and repair costs with precision. I successfully established and maintained strong relationships with clients and shipowners, consistently delivering competitive and accurate cost estimates for repairs and modifications. My role involved developing detailed bid costs, managing tender documents, and coordinating project schedules to ensure timely and efficient execution. By sourcing and evaluating top contractors and negotiating favorable pricing terms, I optimized project outcomes while ensuring all onboard activities were accurately captured for invoicing and billing.", "company_name": "SEAGULL PTE. LTD.", "last_updated": "2025-07-07T09:04:28.968763", "highest_level": "manager", "sub_department": "", "company_linkedin_url": "https://www.linkedin.com/company/seagull-marine-pte-ltd"}, {"title": "1st Assistant Marine Engineer", "company": "NAVIG8 SHIPMANAGEMENT PTE. LTD.", "end_date": "2022-02-01", "company_id": 46015131, "department": "Engineering", "is_current": false, "start_date": "2017-10-01", "description": "I led machinery maintenance and electrical overhauls, ensuring operational excellence across oil tankers, chemical tankers, product tankers, and VLCCs. I efficiently organized daily tasks for engineering staff and supervised their performance, maintaining high standards of execution. I implemented SOLAS-compliant safety training, enhancing onboard safety protocols. My role also involved planning and scheduling preventive maintenance, condition-based monitoring, breakdown repairs, and overseeing new machinery installations. Acting as a guarantee engineer during maiden voyages and as a ship technical superintendent on request, I ensured seamless operations while managing budgets, spares, and consumables to optimize efficiency and cost control.", "company_name": "NAVIG8 SHIPMANAGEMENT PTE. LTD.", "last_updated": "2025-07-07T09:04:28.968763", "highest_level": "entry", "sub_department": "Mechanical", "company_linkedin_url": "https://www.linkedin.com/company/navig8-shipmanagement-pte.-ltd."}, {"title": "Marine Engineer ( Junior Engineer- 2nd Asst Marine Engineer)", "company": "Wallem Maritime Services Inc.", "end_date": "2017-08-01", "company_id": 6417137, "department": "", "is_current": false, "start_date": "2011-03-01", "description": "I managed critical ship operations and crew safety while serving as a marine engineer. I oversaw comprehensive maintenance and repairs of shipboard machinery, specializing in electrical, electronic, and control engineering systems. My expertise extends to ensuring full compliance with CLASS regulations, IMO requirements, and SOLAS standards for international maritime operations. I consistently applied best practices in ship management and technical operations to maintain vessel safety and efficiency at sea.", "company_name": "Wallem Maritime Services Inc.", "last_updated": "2025-07-07T09:04:28.968763", "highest_level": "individual contributor", "sub_department": "", "company_linkedin_url": "https://www.linkedin.com/company/wallem-maritime-services-inc-"}]', '[{"end": 2025, "major": null, "start": 2025, "degree": "Internal Auditor ISM -ISPS- MLC", "school": "DNV GL Training"}, {"end": 2021, "major": "Hull Designing", "start": 2020, "degree": null, "school": "Centre of Excellence in Maritime & Shipbuilding Visakhapatnam"}, {"end": 2010, "major": "Naval Architecture and ", "start": 2006, "degree": "Marine Engineering", "school": "CV Raman College of Engineering (CVRCE), Bhubaneswar"}]', '[]', '{"id": 50678854, "fax": null, "name": "NORSE SHIP MANAGEMENT", "links": {"twitter": null, "facebook": null, "linkedin": "https://www.linkedin.com/company/norse-ship-management-pte-ltd", "crunchbase": null}, "phone": null, "domain": "norseshipmanagement.com", "address": {"city": null, "region": null, "street": null, "description": "", "postal_code": null, "country_code": null}, "revenue": null, "industry": null, "sic_codes": [], "description": "Norse is a bespoke ship management company offering tailored solutions for the comprehensive management of vessels, catering to the unique needs of ship owners and operators worldwide.", "email_domain": "norseshipmanagement.com", "year_founded": "2024-01-01", "num_employees": 15, "ticker_symbol": null, "rr_profile_url": "https://rocketreach.co/norse-ship-management-profile_b6c35594c7a58c8b", "website_domain": "norseshipmanagement.com", "funding_investors": null, "industry_keywords": ["ship management", "vessel management", "marine management", "shipping management", "fleet management", "crewing services", "marine services", "ocean shipping", "maritime operations", "ship operations", "technical management", "crew management", "global shipping", "maritime solutions", "vessel operations", "shipping operations", "maritime services"]}', '{"id": 834257479, "tags": [{"id": 25493700, "name": "API Contacts"}], "links": {"linkedin": "https://www.linkedin.com/in/soumya-ojha-marine-engineer"}, "npi_data": null, "profile_list": {"id": 29016828, "name": "API Contacts"}, "region_latitude": 1.352083, "region_longitude": 103.819836, "current_work_email": "soumya.o@norseshipmanagement.com", "current_personal_email": null}', null, null, null, '2025-09-02 08:15:44', '2025-09-02 08:15:44', null);
INSERT INTO marine_marketing.stakeholders (id, vessel_id, company_id, searched_company_id, name, role, personal_email, professional_email, linkedin_url, status, profile_pic, location, city, region, country, country_code, birth_year, current_employer, current_employer_id, current_employer_domain, current_employer_website, current_employer_linkedin_url, recommended_email, emails_json, phones_json, job_history_json, education_json, skills_json, company_json, others_data, created_by, updated_by, deleted_by, created_at, updated_at, deleted_at) VALUES (404, null, 174, null, '李祥涛', 'Technical Superintendent', null, null, 'https://www.linkedin.com/in/祥涛-李-b36170248', 'not queued', 'https://s3.amazonaws.com/media.mixrank.com/profilepic/307d62b8004af015ecddfe34bb37af91', 'Singapore', null, '', 'Singapore', 'SG', null, 'ORION SHIP MANAGEMENT', 47630214, null, null, 'https://www.linkedin.com/company/orion-ship-management', null, '[{"type": "professional", "email": "ltao@orion-ship-management.com", "grade": "F", "smtp_valid": "invalid", "last_validation_check": "2025-05-06"}, {"type": "professional", "email": "litao@orion-ship-management.com", "grade": "F", "smtp_valid": "invalid", "last_validation_check": "2025-05-06"}, {"type": "professional", "email": "lit@orion-ship-management.com", "grade": "F", "smtp_valid": "invalid", "last_validation_check": "2025-05-06"}, {"type": "professional", "email": "li@orion-ship-management.com", "grade": "F", "smtp_valid": "invalid", "last_validation_check": "2025-05-06"}, {"type": "professional", "email": "li.tao@orion-ship-management.com", "grade": "F", "smtp_valid": "invalid", "last_validation_check": "2025-05-06"}]', '[]', '[{"title": "Technical Superintendent", "company": "ORION SHIP MANAGEMENT", "end_date": "Present", "company_id": 47630214, "department": "Engineering", "is_current": true, "start_date": "2018-09-01", "description": "1. Ensure vessels have on board all the required valid statutory, class and other trading certificates. Coordinate with the Class and Flag State authorities, regarding surveys, issuance of extensions to surveys, certificates, recommendations, etc. Verification of the implementation of the new regulations by the ships under his charge. To decide when and where the surveys and service will be carried out. 2. Daily monitoring vessel performance in terms of speed, fuel and lube oil consumption, and any technical issues and take corrective actions in time. 3. Ensure implementation of PLANNED MAINTENANCE PROGRAMME on board ship. Monitoring monthly major R&M job. 4. Scrutinize all SPARES AND STORES REQUISITIONS from the vessel before approval for quotations and ordering. To do price comparison on the spares and stores for the vessels under his care verification of bills for spares, stores and repairs Approval of orders for emergency stores and provisions for the vessels 5. Ensure vessel submits technical and other reports in a timely manner. 6. Study the fuel oil and lub oil analysis reports and advise the ship of the action to be taken. 7. To review the budget v/s running cost of the ships and take corrective measures by way of controlling expenditure. Assist in preparation of ship’s budgets 8. To conduct ship visit twice per year and prepare and submit VIR 9. To coordinate with Crew Manager for the interview, selection, briefing, appraisal and promotion of the officers and crew 10. Preparation of dry-docking specifications by using VSLMAN and make a comparative chart of quotations 11. To update ship’s Operation Condition Assessment/Condition Assessment Summary/Executive Summary on 3 monthly basis. To update Technical Issues on monthly  basis 11. Carry out any additional work assigned by the TM and GM", "company_name": "ORION SHIP MANAGEMENT", "last_updated": "2025-04-19T11:59:18.461002", "highest_level": "senior", "sub_department": "Systems", "company_linkedin_url": "https://www.linkedin.com/company/orion-ship-management"}, {"title": "Chief Engineer", "company": "Nova Carriers", "end_date": "2018-09-01", "company_id": 44647641, "department": "C_suite", "is_current": false, "start_date": "2015-09-01", "description": "", "company_name": "Nova Carriers", "last_updated": "2025-04-19T11:59:18.461002", "highest_level": "cxo", "sub_department": "Executive", "company_linkedin_url": "https://www.linkedin.com/company/nova-carriers"}, {"title": "Chief Engineer", "company": "COSCO SHIPPING Lines", "end_date": "2015-09-01", "company_id": 3282409, "department": "C_suite", "is_current": false, "start_date": "2010-09-01", "description": "", "company_name": "COSCO SHIPPING Lines", "last_updated": "2025-04-19T11:59:18.461002", "highest_level": "cxo", "sub_department": "Executive", "company_linkedin_url": "https://www.linkedin.com/company/china-ocean-shipping-company-cosco-"}, {"title": "Engineer", "company": "COSCO SHIPPING Lines", "end_date": "2010-09-01", "company_id": 3282409, "department": "Engineering", "is_current": false, "start_date": "2000-09-01", "description": "", "company_name": "COSCO SHIPPING Lines", "last_updated": "2025-04-19T11:59:18.461002", "highest_level": "individual contributor", "sub_department": "", "company_linkedin_url": "https://www.linkedin.com/company/china-ocean-shipping-company-cosco-"}]', '[]', '[]', '{"id": 47630214, "fax": null, "name": "ORION SHIP MANAGEMENT", "links": {"twitter": null, "facebook": null, "linkedin": "https://www.linkedin.com/company/orion-ship-management", "crunchbase": null}, "phone": null, "domain": null, "address": {"city": null, "region": null, "street": null, "description": "FR", "postal_code": null, "country_code": "FR"}, "revenue": null, "industry": null, "sic_codes": [], "description": null, "email_domain": "orion-ship-management.com", "year_founded": null, "num_employees": 16, "ticker_symbol": null, "rr_profile_url": "https://rocketreach.co/orion-ship-management-profile_b710de54c4aeaac8", "website_domain": null, "funding_investors": null, "industry_keywords": []}', '{"id": 735188650, "tags": [{"